/**
 * Issue Creator — Publication Overview plug-in for WoodWing Studio
 *
 * Plans a print issue and creates the layouts for it in one go: pick templates
 * for the empty page slots of the issue you are looking at, then push the whole
 * plan to Studio's Planning API (CreateLayouts on editorialplan.php), which
 * instantiates the layouts from their templates with the page numbers already
 * set. No InDesign involved, no file upload, no second login.
 *
 * Runs inside the Publication Overview child application (same-origin iframe)
 * where the PoUiSdk and the relayed ContentStationSdk globals are available.
 * The current brand / issue / edition come from PoUiSdk.currentFilterSetting(),
 * so the plug-in never asks the user what they are looking at.
 *
 * GENERATED FILE NOTICE: dist/issue-creator-plugin.js is generated by
 * build-plugin.js from the files in src/ — edit those and rebuild.
 *
 * Registration (WoodWing Cloud): Management Console → Integrations →
 * Plug-ins → Publication Overview → Add new → URL of the dist file.
 */
(function () {
  'use strict';

  var VERSION = '0.1.1';
  var TAG = '[issue-creator]';

  if (typeof PoUiSdk === 'undefined') {
    // Not in a Publication Overview context (or registered in the wrong plug-in
    // slot in the Management Console) — do nothing, never break the page.
    console.warn(TAG + ' PoUiSdk not available — plug-in not loaded in a Publication Overview context.');
    return;
  }

  // ─── Defaults ──────────────────────────────────────────────────────────────
  // Naming pattern tokens: {issue} {brand} {template} {page} {pageend}
  // {pagerange}. Page tokens take :0N zero-padding, e.g. {page:03} -> 007.
  var DEFAULTS = {
    layoutPattern: '{brand}_p{page:03}_{template}',
    // Left null until a brand nominates one; empty slots are skipped without it.
    defaultTemplateId: null,
    // Anything whose name contains this is offered as the blank-page template.
    blankTemplateHint: 'blank',
  };

  var SETTINGS_KEY = 'issueCreator.settings';

  function loadSettings() {
    try {
      var raw = window.localStorage.getItem(SETTINGS_KEY);
      return raw ? Object.assign({}, DEFAULTS, JSON.parse(raw)) : Object.assign({}, DEFAULTS);
    } catch (e) {
      return Object.assign({}, DEFAULTS);
    }
  }

  function saveSettings(s) {
    try {
      window.localStorage.setItem(SETTINGS_KEY, JSON.stringify(s));
    } catch (e) {
      console.warn(TAG + ' could not persist settings: ' + e.message);
    }
  }

  // ─── Studio Server API (same origin — cookie session) ─────────────────────
  // Requests authenticate via the session cookie plus the X-WoodWing-Application
  // header (CSRF guard), with Ticket null in the payload. On older ticket-based
  // setups getInfo().Ticket is populated and used instead. Proven against
  // lab-studio for both index.php (workflow) and editorialplan.php (planning) —
  // the planning endpoint accepting this session is what makes a plug-in viable
  // at all; see research/planning-api-and-ids-jobs.md.
  var WW_APP = 'Content Station';
  var WW_APP_HEADER = { 'X-WoodWing-Application': WW_APP };

  function getTicket() {
    try {
      var info = ContentStationSdk.getInfo();
      return (info && info.Ticket) || '';
    } catch (e) { return ''; }
  }

  // The PO iframe lives at /app/publicationoverview/, so host-absolute paths are
  // the safe default; csConfig is used when it is exposed in this frame.
  function serverUrl(script) {
    var base = (window.csConfig && window.csConfig.serverUrl) || '/server/index.php';
    var rel = base.replace(/[^/]+$/, script);
    return new URL(rel, window.location.href).href;
  }

  function rpc(script, method, params) {
    params = params || {};
    if (!('Ticket' in params) || !params.Ticket) params.Ticket = getTicket() || null;
    return fetch(serverUrl(script) + '?protocol=JSON&method=' + encodeURIComponent(method), {
      method: 'POST',
      credentials: 'same-origin',
      headers: Object.assign({ 'Content-Type': 'application/json' }, WW_APP_HEADER),
      body: JSON.stringify({ method: method, id: '1', params: [params], jsonrpc: '2.0' }),
    }).then(function (r) {
      if (!r.ok) throw new Error(method + ' failed: HTTP ' + r.status);
      return r.json();
    }).then(function (j) {
      if (j.error) {
        console.error(TAG + ' ' + method + ' error response:', j.error);
        var e = j.error;
        var parts = [];
        if (e.message) parts.push(e.message);
        if (e.data && e.data.detail && e.data.detail !== e.message) parts.push(e.data.detail);
        if (e.code) parts.push('(code ' + e.code + ')');
        throw new Error(method + ' failed: ' + (parts.join(' — ') || JSON.stringify(e)));
      }
      return j.result;
    });
  }

  function callServer(method, params) { return rpc('index.php', method, params); }
  function callPlanning(method, params) { return rpc('editorialplan.php', method, params); }

  function notify(content, type) {
    try {
      ContentStationSdk.showNotification({ content: content, type: type || 'default', timeout: 6000, showX: true });
    } catch (e) {
      console.info(TAG + ' ' + content);
    }
  }

  function currentFilter() {
    try { return PoUiSdk.currentFilterSetting() || {}; } catch (e) { return {}; }
  }

  // ─── Planning API (editorialplan.php) ─────────────────────────────────────
  // CreateLayouts instantiates layouts from their templates with the page plan
  // already applied — Page.PageOrder is the real page number. This replaces the
  // old PoC pipeline entirely (download native -> upload to transfer server ->
  // CreateObjects -> relate -> target -> renumber via local InDesign).
  //
  // Studio's JSON-RPC is strongly typed: nested objects need a __classname__ or
  // the deserializer drops every field and reports them as unspecified. The
  // planning interface's exact type names are not in the SDK docs, so the
  // strategy is configurable and confirmProtocol() below pins it down.

  var CLASSNAME_STRATEGIES = {
    // Matches the workflow interface convention (bare entity names).
    bare: { fromTemplate: 'LayoutFromTemplate', layout: 'Layout', page: 'Page' },
    // Matches the Pln prefix seen on PlnCreateLayoutsResponse.
    pln: { fromTemplate: 'PlnLayoutFromTemplate', layout: 'PlnLayout', page: 'PlnPage' },
    // No markers at all — known to fail, kept so confirmProtocol can prove it.
    none: { fromTemplate: null, layout: null, page: null },
  };

  var strategy = 'bare';

  function cls(name) { return name ? { __classname__: name } : {}; }

  // slot: { page, pageEnd, templateId, templateName, name }
  // ctx:  { publication, issue, pubChannel, section }
  function buildLayoutFromTemplate(slot, ctx) {
    var s = CLASSNAME_STRATEGIES[strategy];
    var end = slot.pageEnd || slot.page;
    var pages = [];
    for (var p = slot.page, seq = 1; p <= end; p++, seq++) {
      pages.push(Object.assign(cls(s.page), { PageOrder: p, PageSequence: seq }));
    }
    return Object.assign(cls(s.fromTemplate), {
      // The probe used the template's name; ids may also be accepted.
      Template: slot.templateName || slot.templateId,
      NewLayout: Object.assign(cls(s.layout), {
        Name: slot.name,
        Publication: ctx.publication,
        Issue: ctx.issue,
        PubChannel: ctx.pubChannel,
        Section: ctx.section,
        Pages: pages,
        // Status is deliberately never sent: the SDK docs state that object
        // state is determined by the editorial system, not the plan system.
      }),
    });
  }

  // Create many layouts in one request — CreateLayouts takes an array, so a
  // whole issue can go up at once.
  function createLayouts(slots, ctx) {
    var payload = { Layouts: slots.map(function (slot) { return buildLayoutFromTemplate(slot, ctx); }) };
    return callPlanning('CreateLayouts', payload).then(function (r) {
      return (r && r.Layouts) || [];
    });
  }

  // Does the endpoint accept our session at all? An empty Layouts array is a
  // no-op that still exercises authentication, so this has no side effects.
  function checkPlanningAccess() {
    return callPlanning('CreateLayouts', { Layouts: [] })
      .then(function () { return true; })
      .catch(function (e) {
        console.warn(TAG + ' planning access check failed: ' + e.message);
        return false;
      });
  }

  // One-off: work out which __classname__ strategy this server wants by
  // creating a single throwaway layout. Sets `strategy` on success. Exposed on
  // the debug object rather than run automatically — it creates a real object.
  function confirmProtocol(slot, ctx) {
    var order = ['bare', 'pln', 'none'];
    var attempt = 0;
    function next() {
      if (attempt >= order.length) {
        return Promise.reject(new Error('No __classname__ strategy worked; see console for each error.'));
      }
      var candidate = order[attempt++];
      var previous = strategy;
      strategy = candidate;
      return createLayouts([slot], ctx).then(function (layouts) {
        if (!layouts.length || !layouts[0].Id) {
          console.warn(TAG + ' strategy "' + candidate + '" accepted but returned no layout');
          strategy = previous;
          return next();
        }
        console.info(TAG + ' __classname__ strategy confirmed: "' + candidate + '"', layouts[0]);
        return { strategy: candidate, layout: layouts[0] };
      }).catch(function (e) {
        console.warn(TAG + ' strategy "' + candidate + '" -> ' + e.message);
        strategy = previous;
        return next();
      });
    }
    return next();
  }

  // ─── Issue data ────────────────────────────────────────────────────────────
  // GetPagesInfo is the service Publication Overview itself renders from, so it
  // is the authority on which pages of the issue are already occupied — and on
  // where a created layout actually lands. Probe layout 87902 confirmed that
  // position here follows the planning data, not the INDD's own numbering.

  function loadIssueModel(issueId, editionId) {
    return callServer('GetPagesInfo', {
      Issue: { Id: String(issueId), __classname__: 'Issue' },
      IDs: null,
      Edition: editionId ? { Id: String(editionId), __classname__: 'Edition' } : null,
      Category: null,
      State: null,
    }).then(function (r) {
      var layouts = {};
      var los = r.LayoutObjects || [];
      for (var i = 0; i < los.length; i++) {
        var lo = los[i];
        layouts[String(lo.Id)] = {
          id: String(lo.Id),
          name: lo.Name,
          stateName: (lo.State && lo.State.Name) || '',
          lockedBy: lo.LockedBy || '',
        };
      }

      var pages = [];
      var eps = r.EditionsPages || [];
      for (var e = 0; e < eps.length; e++) {
        var pos = eps[e].PageObjects || [];
        for (var p = 0; p < pos.length; p++) {
          var po = pos[p];
          pages.push({
            layoutId: String(po.ParentLayoutId),
            pageOrder: Number(po.PageOrder),
            pageNumber: String(po.PageNumber),
            pageSequence: Number(po.PageSequence),
          });
        }
      }
      pages.sort(function (a, b) { return a.pageOrder - b.pageOrder || a.pageSequence - b.pageSequence; });

      return {
        issueId: String(issueId),
        editionId: editionId ? String(editionId) : null,
        expectedPages: Number(r.ExpectedPages) || 0,
        layouts: layouts,
        pages: pages,
        occupied: pages.reduce(function (set, pg) { set[pg.pageOrder] = pg.layoutId; return set; }, {}),
      };
    });
  }

  // Names are what the Planning API identifies brand/issue/channel/section by,
  // and currentFilterSetting() only gives ids — so resolve them once.
  //
  // The brand is deliberately resolved by finding which publication actually
  // contains the issue, rather than trusting a brand id off the filter. The
  // filter's key for it is undocumented and was not `brandId` on this server,
  // and guessing wrong is silently catastrophic: PublicationIds null returns
  // every brand, and taking the first gives a plausible-looking but completely
  // unrelated brand.
  function findIssue(publications, issueId) {
    for (var p = 0; p < publications.length; p++) {
      var pub = publications[p];
      var chans = pub.PubChannels || [];
      for (var c = 0; c < chans.length; c++) {
        var issues = chans[c].Issues || [];
        for (var i = 0; i < issues.length; i++) {
          if (String(issues[i].Id) === String(issueId)) {
            return { pub: pub, channel: chans[c], issue: issues[i] };
          }
        }
      }
    }
    return null;
  }

  function loadContextNames(filter) {
    // Whatever the filter calls the brand, use it as a hint to keep the common
    // case to one small response; fall back to every brand if the issue is not
    // in there.
    var hint = filter.brandId || filter.publicationId || filter.pubId || filter.brand || null;
    var request = { RequestInfo: ['PubChannels', 'Issues', 'Categories'] };

    function fetchPubs(ids) {
      return callServer('GetPublications', Object.assign({ PublicationIds: ids }, request))
        .then(function (r) { return r.Publications || []; });
    }

    return fetchPubs(hint ? [String(hint)] : null).then(function (pubs) {
      var found = findIssue(pubs, filter.issueId);
      if (found) return found;
      // Hint was absent, wrong, or pointed at a brand without this issue.
      if (hint) {
        return fetchPubs(null).then(function (all) { return findIssue(all, filter.issueId); });
      }
      return null;
    }).then(function (found) {
      if (!found) throw new Error('Could not find issue ' + filter.issueId + ' in any brand you can read');

      // Section is Studio's Category. The user may be filtered to "All
      // categories", in which case there is nothing to infer — but created
      // layouts still need one, so fall back to the brand's first and say so
      // rather than choosing silently.
      var cats = found.pub.Categories || [];
      var sectionName = '';
      var defaulted = false;
      for (var k = 0; k < cats.length; k++) {
        if (String(cats[k].Id) === String(filter.categoryId)) { sectionName = cats[k].Name; break; }
      }
      if (!sectionName && cats.length) { sectionName = cats[0].Name; defaulted = true; }

      return {
        publication: found.pub.Name,
        publicationId: String(found.pub.Id),
        issue: found.issue.Name,
        issueId: String(found.issue.Id),
        pubChannel: found.channel.Name,
        pubChannelId: String(found.channel.Id),
        section: sectionName,
        sectionDefaulted: defaulted,
        categories: cats.map(function (c) { return { id: String(c.Id), name: c.Name }; }),
      };
    });
  }

  // ─── Layout templates ──────────────────────────────────────────────────────

  // A template's page count comes from its PageRange metadata: "002-005" is a
  // 4-page template, so assigning it to a slot spans four consecutive pages.
  function parseRange(s) {
    var m = /^(\d+)(?:\s*-\s*(\d+))?$/.exec(String(s || '').trim());
    if (!m) return null;
    var a = Number(m[1]);
    var b = m[2] ? Number(m[2]) : a;
    return { start: a, end: Math.max(a, b) };
  }

  function templatePageCount(pageRange) {
    var r = parseRange(pageRange);
    return r ? (r.end - r.start + 1) : 1;
  }

  function loadTemplates(publicationId) {
    return callServer('QueryObjects', {
      Params: [
        { __classname__: 'QueryParam', Property: 'Type', Operation: '=', Value: 'LayoutTemplate' },
        { __classname__: 'QueryParam', Property: 'PublicationId', Operation: '=', Value: String(publicationId) },
      ],
      FirstEntry: 1,
      MaxEntries: 200,
      Hierarchical: false,
      Order: [],
      MinimalProps: ['ID', 'Name', 'Category', 'PageRange', 'Modified'],
      RequestProps: null,
      Areas: ['Workflow'],
      GetHidden: false,
    }).then(function (r) {
      var cols = (r.Columns || []).map(function (c) { return c.Name; });
      return (r.Rows || []).map(function (row) {
        var o = {};
        for (var i = 0; i < cols.length; i++) o[cols[i]] = row[i];
        return {
          id: String(o.ID),
          name: o.Name,
          category: o.Category,
          pageRange: o.PageRange,
          pageCount: templatePageCount(o.PageRange),
          modified: o.Modified,
        };
      });
    });
  }

  // Whichever template looks like the brand's blank page, for filling empty slots.
  function guessBlankTemplate(templates, hint) {
    var needle = String(hint || 'blank').toLowerCase();
    for (var i = 0; i < templates.length; i++) {
      if (String(templates[i].name).toLowerCase().indexOf(needle) !== -1) return templates[i];
    }
    return null;
  }

  // ─── Naming patterns ───────────────────────────────────────────────────────
  // Ported unchanged from the Electron PoC, where it was exercised across
  // several real issue builds. Tokens: {issue} {brand} {template} {page}
  // {pageend} {pagerange}; page tokens take :0N zero-padding.

  function applyPattern(pattern, ctx) {
    function pad(n, w) { return String(n).padStart(Number(w), '0'); }
    function range(w) {
      return ctx.pageEnd > ctx.page ? pad(ctx.page, w) + '-' + pad(ctx.pageEnd, w) : pad(ctx.page, w);
    }
    return String(pattern)
      .replace(/\{pagerange:0(\d)\}/g, function (_, w) { return range(w); })
      .replace(/\{pagerange\}/g, function () { return range(1); })
      .replace(/\{pageend:0(\d)\}/g, function (_, w) { return pad(ctx.pageEnd, w); })
      .replace(/\{pageend\}/g, String(ctx.pageEnd))
      .replace(/\{page:0(\d)\}/g, function (_, w) { return pad(ctx.page, w); })
      .replace(/\{page\}/g, String(ctx.page))
      .replace(/\{issue\}/g, ctx.issue || '')
      .replace(/\{brand\}/g, ctx.brand || '')
      .replace(/\{template\}/g, ctx.template || '');
  }

  // Fill in slot.name for a set of slots about to be created.
  function nameSlots(slots, pattern, ctx) {
    return slots.map(function (slot) {
      var end = slot.pageEnd || slot.page;
      return Object.assign({}, slot, {
        pageEnd: end,
        name: applyPattern(pattern, {
          page: slot.page,
          pageEnd: end,
          issue: ctx.issue,
          brand: ctx.publication,
          template: slot.templateName,
        }),
      });
    });
  }

  // ─── Planner dialog ────────────────────────────────────────────────────────
  // SCAFFOLD: this proves the whole plumbing end to end — context resolution,
  // planning-endpoint access, template listing, occupied-page detection — and
  // hosts the protocol confirmation. The slot grid and template gallery from the
  // Electron PoC land here next.

  var DIALOG_CSS = [
    '.ic-overlay{position:fixed;inset:0;background:rgba(0,0,0,.45);z-index:99999;display:flex;align-items:center;justify-content:center}',
    '.ic-dialog{background:#fff;color:#222;border-radius:6px;min-width:560px;max-width:80vw;max-height:80vh;',
    '  display:flex;flex-direction:column;font:13px/1.5 system-ui,sans-serif;box-shadow:0 8px 40px rgba(0,0,0,.35)}',
    '.ic-dialog h2{margin:0;padding:14px 18px;border-bottom:1px solid #e3e3e3;font-size:15px;font-weight:600}',
    '.ic-body{padding:14px 18px;overflow:auto}',
    '.ic-body dl{display:grid;grid-template-columns:auto 1fr;gap:4px 14px;margin:0 0 12px}',
    '.ic-body dt{color:#666}',
    '.ic-body dd{margin:0}',
    '.ic-list{max-height:180px;overflow:auto;border:1px solid #e3e3e3;border-radius:4px;padding:6px 10px;margin:0 0 12px}',
    '.ic-list div{padding:2px 0}',
    '.ic-muted{color:#777}',
    '.ic-ok{color:#137333}',
    '.ic-bad{color:#c5221f}',
    '.ic-actions{padding:12px 18px;border-top:1px solid #e3e3e3;display:flex;justify-content:flex-end;gap:8px}',
    '.ic-actions button{padding:6px 14px;border-radius:4px;border:1px solid #bbb;background:#f6f6f6;cursor:pointer}',
    '.ic-actions button.ic-primary{background:#1a73e8;border-color:#1a73e8;color:#fff}',
  ].join('\n');

  function injectCss() {
    if (document.getElementById('ic-styles')) return;
    var style = document.createElement('style');
    style.id = 'ic-styles';
    style.textContent = DIALOG_CSS;
    document.head.appendChild(style);
  }

  function el(tag, props, children) {
    var node = document.createElement(tag);
    props = props || {};
    Object.keys(props).forEach(function (k) {
      if (k === 'text') node.textContent = props[k];
      else if (k === 'class') node.className = props[k];
      else node.setAttribute(k, props[k]);
    });
    (children || []).forEach(function (c) { if (c) node.appendChild(c); });
    return node;
  }

  function openPlannerDialog() {
    injectCss();
    var filter = currentFilter();
    if (!filter.issueId) {
      notify('Open an issue in Publication Overview first.', 'error');
      return;
    }

    var ctxList = el('dl');
    var accessLine = el('div', { class: 'ic-muted', text: 'Checking planning access…' });
    var freeLine = el('div', { class: 'ic-muted', text: '' });
    var templateList = el('div', { class: 'ic-list', text: 'Loading templates…' });

    var closeBtn = el('button', { text: 'Close' });
    var confirmBtn = el('button', { class: 'ic-primary', text: 'Confirm protocol' });
    confirmBtn.disabled = true;

    var dialog = el('div', { class: 'ic-dialog' }, [
      el('h2', { text: 'Issue Creator — scaffold v' + VERSION }),
      el('div', { class: 'ic-body' }, [ctxList, accessLine, freeLine, templateList]),
      el('div', { class: 'ic-actions' }, [closeBtn, confirmBtn]),
    ]);
    var overlay = el('div', { class: 'ic-overlay' }, [dialog]);
    document.body.appendChild(overlay);

    function close() { if (overlay.parentNode) overlay.parentNode.removeChild(overlay); }
    closeBtn.addEventListener('click', close);
    overlay.addEventListener('click', function (ev) { if (ev.target === overlay) close(); });

    function row(term, value) {
      ctxList.appendChild(el('dt', { text: term }));
      ctxList.appendChild(el('dd', { text: value }));
    }

    var state = { ctx: null, templates: [], model: null };

    checkPlanningAccess().then(function (ok) {
      accessLine.className = ok ? 'ic-ok' : 'ic-bad';
      accessLine.textContent = ok
        ? 'Planning endpoint reachable on this session.'
        : 'Planning endpoint rejected this session — this account may lack planning rights.';
      confirmBtn.disabled = !ok;
    });

    // The filter's key names are undocumented and not all are what the notes
    // suggest — log the raw object so a wrong assumption is visible, not silent.
    console.info(TAG + ' currentFilterSetting():', filter);

    loadContextNames(filter).then(function (ctx) {
      state.ctx = ctx;
      row('Brand', ctx.publication + ' (' + ctx.publicationId + ')');
      row('Issue', ctx.issue + ' (' + ctx.issueId + ')');
      row('Channel', ctx.pubChannel + ' (' + ctx.pubChannelId + ')');
      row('Section', ctx.section
        ? ctx.section + (ctx.sectionDefaulted ? ' — defaulted, no category selected' : '')
        : '— none available');
      return loadTemplates(ctx.publicationId);
    }).then(function (templates) {
      state.templates = templates;
      templateList.textContent = '';
      if (!templates.length) {
        templateList.appendChild(el('div', { class: 'ic-muted', text: 'No layout templates in this brand.' }));
        return;
      }
      templates.forEach(function (t) {
        templateList.appendChild(el('div', {
          text: t.name + '  —  ' + t.pageCount + 'pp' + (t.pageRange ? ' (' + t.pageRange + ')' : ''),
        }));
      });
      var blank = guessBlankTemplate(templates, loadSettings().blankTemplateHint);
      if (blank) templateList.appendChild(el('div', { class: 'ic-muted', text: 'Blank-page template: ' + blank.name }));
    }).catch(function (e) {
      templateList.textContent = 'Failed: ' + e.message;
      templateList.className = 'ic-list ic-bad';
    });

    loadIssueModel(filter.issueId, filter.editionId).then(function (model) {
      state.model = model;
      var taken = Object.keys(model.occupied).map(Number).sort(function (a, b) { return a - b; });
      freeLine.textContent = model.expectedPages
        ? model.expectedPages + ' pages expected, ' + taken.length + ' already occupied' +
          (taken.length ? ' (' + taken.join(', ') + ')' : '')
        : taken.length + ' pages already occupied';
    }).catch(function (e) {
      freeLine.className = 'ic-bad';
      freeLine.textContent = 'Could not read issue pages: ' + e.message;
    });

    // Step 2 of the build plan: pin down the __classname__ strategy by creating
    // one throwaway layout on the first free page, through the real client.
    confirmBtn.addEventListener('click', function () {
      if (!state.ctx) { notify('Still resolving the brand and issue — try again in a moment.', 'error'); return; }
      if (!state.templates.length) {
        notify('No layout templates in ' + state.ctx.publication + ', so there is nothing to create from.', 'error');
        return;
      }
      var template = state.templates[0];
      var page = 1;
      while (state.model && state.model.occupied[page]) page++;
      var slot = {
        page: page,
        pageEnd: page + template.pageCount - 1,
        templateId: template.id,
        templateName: template.name,
        name: 'PROTOCOL-CHECK-' + new Date().toISOString().slice(0, 10),
      };
      confirmBtn.disabled = true;
      confirmBtn.textContent = 'Creating…';
      confirmProtocol(slot, state.ctx).then(function (res) {
        notify('Protocol confirmed: "' + res.strategy + '" — layout ' + res.layout.Id + ' created on page ' + page + '. Delete it when done.', 'default');
        confirmBtn.textContent = 'Confirmed: ' + res.strategy;
      }).catch(function (e) {
        notify('Protocol check failed: ' + e.message, 'error');
        confirmBtn.disabled = false;
        confirmBtn.textContent = 'Confirm protocol';
      });
    });
  }

  // ─── Registration & lifecycle ──────────────────────────────────────────────
  try {
    if (PoUiSdk.hasActions()) PoUiSdk.createAction(); // separator below other plug-ins
    PoUiSdk.createAction({
      label: 'Create pages…',
      click: function () {
        try { openPlannerDialog(); }
        catch (e) {
          console.error(TAG + ' planner dialog failed:', e);
          notify('Issue Creator failed to open: ' + e.message, 'error');
        }
      },
    });
  } catch (e) {
    console.error(TAG + ' could not register menu action:', e);
  }

  // Console diagnostics: window.__issueCreator
  window.__issueCreator = {
    version: VERSION,
    settings: loadSettings,
    saveSettings: saveSettings,
    currentFilter: currentFilter,
    loadContextNames: loadContextNames,
    loadIssueModel: loadIssueModel,
    loadTemplates: loadTemplates,
    checkPlanningAccess: checkPlanningAccess,
    confirmProtocol: confirmProtocol,
    createLayouts: createLayouts,
    applyPattern: applyPattern,
    nameSlots: nameSlots,
    open: openPlannerDialog,
    strategy: function () { return strategy; },
  };

  console.info(TAG + ' v' + VERSION + ' loaded');

})();
